@router.post(
    "/register",
    response_model=AccountResponse,
    status_code=status.HTTP_201_CREATED,
)
def register_account(
    request: RegisterRequest,
    response: Response,
    database: Annotated[Session, Depends(get_db)],
) -> AccountResponse:
    """Create an Account, hash its password, and establish a signed session."""
    normalized_username = request.username.lower()
    existing_account_id = database.scalar(
        select(Account.id).where(func.lower(Account.username) == normalized_username)
    )
    if existing_account_id is not None:
        raise ApiHTTPException(
            status_code=409,
            code="auth_username_taken",
            detail="Username is already registered",
            headers=NO_STORE_HEADERS,
        )

    account = Account(
        username=request.username,
        password_hash=hash_password(request.password),
    )
    database.add(account)
    try:
        database.commit()
    except IntegrityError as error:
        database.rollback()
        raise ApiHTTPException(
            status_code=409,
            code="auth_username_taken",
            detail="Username is already registered",
            headers=NO_STORE_HEADERS,
        ) from error

    database.refresh(account)
    _set_session_cookie(response, account.id)
    return _public_account(account)


@router.post("/login", response_model=AccountResponse)
def login_account(
    request: LoginRequest,
    response: Response,
    database: Annotated[Session, Depends(get_db)],
) -> AccountResponse:
    """Verify Account credentials and establish a signed session."""
    account = database.scalar(
        select(Account).where(func.lower(Account.username) == request.username.lower())
    )
    encoded_hash = account.password_hash if account is not None else DUMMY_PASSWORD_HASH
    credentials_valid = verify_password(request.password, encoded_hash)
    if account is None or not credentials_valid:
        raise ApiHTTPException(
            status_code=401,
            code="auth_invalid_credentials",
            detail="Invalid username or password",
            headers=NO_STORE_HEADERS,
        )

    account.last_login_at = datetime.now(UTC)
    database.commit()
    _set_session_cookie(response, account.id)
    return _public_account(account)


